const updateRunStatusFrom = `-- name: UpdateRunStatusFrom :one
UPDATE procurement.inquiry_runs
SET
    status = $4,
    sent_at = CASE WHEN $4 = 'sending' THEN COALESCE(sent_at, NOW()) ELSE sent_at END,
    completed_at = CASE
        WHEN $4 IN ('completed', 'partially_answered', 'failed', 'cancelled')
        THEN COALESCE(completed_at, NOW())
        ELSE completed_at
    END,
    updated_at = NOW()
WHERE id = $1 AND organization_id = $2 AND status = $3
RETURNING id, organization_id, status, source, schedule_ref, nota, created_by_member_id, sent_at, completed_at, created_at, updated_at
`

